(3023, 'Čakovec', 'Gradski bazeni Marija Ružić Čakovec', 'Termalni bazeni', 'mid', 'Kupnja dnevne ulaznice za rekreacijsko plivanje u unutarnjim bazenima, korištenje jacuzzija i bogatog kompleksa sauna.', '2026-05-27 11:14:46'),
(3024, 'Čakovec', 'Kupnja autohtonih međimurskih suvenira u muzeju', 'Lagani shopping', 'mid', 'Kupnja replika povijesnog nakita Zrinskih, ručno rađenih predmeta od šibe i tradicionalnih licitarskih srca.', '2026-05-27 11:14:46'),
(3025, 'Čakovec', 'Spust kajacima niz stari tok rijeke Drave', 'Kajaking', 'mid', 'Poludnevni organizirani najam kajaka i vođeni spust po očuvanom i mirnom prirodnom toku rijeke u okolici grada.', '2026-05-27 11:14:46'),
(3026, 'Čakovec', 'Škola jahanja u konjičkom klubu u Međimurju', 'Jahanje', 'mid', 'Jednosatni uvodni sat jahanja s instruktorom na uređenim stazama seoskog imanja u prirodi.', '2026-05-27 11:14:46'),
(3027, 'Čakovec', 'Kampiranje na uređenom seoskom OPG-u u okolici', 'Kampiranje', 'mid', 'Noćenje na parceli za šatore s pristupom domaćim životinjama, domaćoj hrani i vinima gornjeg Međimurja.', '2026-05-27 11:14:46'),
(3028, 'Čakovec', 'Road trip po Međimurskoj vinskoj cesti', 'Road trip', 'mid', 'Jednodnevni izlet automobilom kroz pitoreskne brežuljke uz posjet malim obiteljskim vinarijama i kušanje Pušipela.', '2026-05-27 11:14:46'),
(3029, 'Čakovec', 'Razgledavanje Muzeja Međimurja Čakovec', 'Muzeji', 'mid', 'Kupnja ulaznice za detaljan obilazak bogatog povijesnog i etnografskog postava smještenog u unutrašnjosti dvorca Zrinskih.', '2026-05-27 11:14:46'),
(3030, 'Čakovec', 'Posjet Izložbenom salonu Muzeja Međimurja', 'Galerije', 'mid', 'Kupnja karte za razgledavanje povremenih i stalnih umjetničkih izložbi akademskih slikara i kipara iz regije.', '2026-05-27 11:14:46'),
(3031, 'Čakovec', 'Stručni razgled Čakovec - grad Zrinskih', 'Walking tour', 'mid', 'Dvosatni vođeni obilazak s lokalnim vodičem, fokusiran na zlatno doba grada pod plemićkom obitelji Zrinski i tajne dvorca.', '2026-05-27 11:14:46'),
(3032, 'Čakovec', 'Shopping u trgovačkom centru Galerija Sjever', 'Shopping', 'mid', 'Obilazak trgovina poznatih modnih brendova, kozmetike i tehničke robe u najvećem retail parku u Čakovcu.', '2026-05-27 11:14:46'),
(3033, 'Čakovec', 'Degustacija Pušipela u modernoj kušaonici', 'Vinarije', 'mid', 'Posjet podrumu u okolici grada i edukativno kušanje autohtone međimurske sorte vina Pušipel uz domaći narezak.', '2026-05-27 11:14:46'),
(3034, 'Čakovec', 'Gastro tura Okusi tradicije Međimurja', 'Food tour', 'mid', 'Vođeni obilazak dva tradicionalna restorana uz kušanje pretepene juhe i pečenog patke s mlincima.', '2026-05-27 11:14:46'),
(3035, 'Čakovec', 'Kušanje piva u čakovečkoj pivovari Lepi Dečki', 'Craft pivovare', 'mid', 'Degustacija poznatih domaćih craft piva direktno u ugodnom ambijentu njihovog puba.', '2026-05-27 11:14:46'),
(3036, 'Čakovec', 'Posjet mini sirani uz kušanje turoša', 'Degustacija sira', 'mid', 'Organizirana prezentacija ručne izrade sušenog sira stožastog oblika s dodatkom češnjaka i ljute paprike.', '2026-05-27 11:14:46'),
(3037, 'Čakovec', 'Vinska proba u povijesnom podrumu dvorca', 'Degustacija vina', 'mid', 'Sommelierski vođena degustacija tri vrste kontinentalnih vina u autentičnom kamenom podrumu Starog grada.', '2026-05-27 11:14:46'),
(3038, 'Čakovec', 'Riječni smuđ u bučinim sjemenkama u restoranu Barok', 'Seafood', 'mid', 'Kušanje svježe riječne ribe pripremljene na moderan način s lokalnim namirnicama u ugodnom gradskom ambijentu.', '2026-05-27 11:14:46'),
(3039, 'Čakovec', 'Meso z tiblice u restoranu Shamper', 'Tradicionalni restoran', 'mid', 'Tradicionalni ručak koji uključuje vrhunsko konzervirano svinjsko meso iz drvene posude posluženo s domaćim kruhom.', '2026-05-27 11:14:46'),
(3040, 'Čakovec', 'Predstave u Centru za kulturu Čakovec', 'Kazalište', 'mid', 'Kupnja ulaznice za dramske i komične izvedbe gostujućih hrvatskih kazališta i koncerata u glavnoj gradskoj dvorani.', '2026-05-27 11:14:46'),
(3041, 'Čakovec', 'Noćni izlazak i zabava u Metalac Industrial Baru', 'Klubovi', 'mid', 'Vikend izlazak, ples i slušanje rock, alternativne ili klupske glazbe u kultnom preuređenom tvorničkom prostoru.', '2026-05-27 11:14:46'),
(3042, 'Čakovec', 'Koktel večer u Caffe Baru Podroom', 'Cocktail bar', 'mid', 'Uživanje u izvrsno pripremljenim koktelima u jedinstvenom pub ambijentu pod zemljom koji je centar noćnog života.', '2026-05-27 11:14:46'),
(3043, 'Čakovec', 'Koncerti regionalnih izvođača na Porcijunkulovu', 'Live music', 'mid', 'Slušanje pop i rock koncerata na velikoj open-air pozornici postavljenoj u samom centru grada u sklopu festivala.', '2026-05-27 11:14:46'),
(3044, 'Čakovec', 'Stand-up večer u lokalnom pubu', 'Stand-up show', 'mid', 'Kupnja ulaznice za nastupe popularnih regionalnih komičara uz vrhunsko craft pivo i lokalno društvo.', '2026-05-27 11:14:46'),
(3045, 'Čakovec', 'Gourmet pizza s mesom z tiblice u Pizzeriji Stari Hrast', 'Street food', 'mid', 'Uživanje u izvrsnoj pizzi iz krušne peći s lokalnim međimurskim sastojcima u kasnim večernjim satima.', '2026-05-27 11:14:46'),
(3046, 'Čakovec', 'Filmska projekcija u Kinu Centra za kulturu', 'Kazalište', 'mid', 'Gledanje najnovijih holivudskih blockbustera ili sinkroniziranih crtića u udobnoj dvorani gradskog kina.', '2026-05-27 11:14:46'),
(3047, 'Čakovec', 'Ekskluzivni VIP wellness paket u Termama Sveti Martin', 'Wellness', 'high', 'Luksuzni transfer iz Čakovca, privatni zakup spa i jacuzzi zone, masaža s uljem grožđanih koštica i pjenušac za dvoje.', '2026-05-27 11:14:46'),
(3048, 'Čakovec', 'Adrenalinski dan u gornjem Međimurju', 'Zipline', 'high', 'Privatni jednodnevni izlet koji uključuje sportske aktivnosti, spustove na zipline žicama i bogat ručak u elitnom vinskom dvorcu.', '2026-05-27 11:14:46'),
(3049, 'Čakovec', 'VIP Foto-safari kroz zaštićeni krajolik rijeke Mure', 'Safari', 'high', 'Ekskluzivna vožnja otvorenim terenskim vozilima kroz šumske rezervate i močvarna područja radi slikanja rijetkih ptica i dabrova.', '2026-05-27 11:14:46'),
(3050, 'Čakovec', 'Cjelodnevna Quad ekspedicija međimurskim brežuljcima', 'Off-road tura', 'high', 'Najam moćnih quad vozila i privatno vođena tura kroz šumske i vinogradarske puteve uz organizirani lovački ručak.', '2026-05-27 11:14:46'),
(3051, 'Čakovec', 'Gourmet večera od 7 sljedova u restoranu Shamper', 'Fine dining', 'high', 'Ekskluzivni meni modernih interpretacija tradicijske međimurske kuhinje, uparen s vrhunskim lokalnim pjenušcima.', '2026-05-27 11:14:46'),
(3052, 'Čakovec', 'Privatni masterclass pripreme Međimurske gibanice', 'Kuharski tečaj', 'high', 'Individualna kulinarska radionica u privatnom studiju, učenje tajni tankog tijesta i slaganja slojeva tradicionalnog kolača.', '2026-05-27 11:14:46'),
(3053, 'Čakovec', 'Ekskluzivni najam povijesnog salona dvorca Zrinskih', 'Dvorci', 'high', 'Organizacija luksuznog privatnog cateringa, bakljade i večere u autentičnom renesansnom ambijentu Starog grada.', '2026-05-27 11:14:46'),
(3054, 'Čakovec', 'VIP party s pogledom na dvorac i Perivoj Zrinskih', 'Rooftop bar', 'high', 'Zatvoreni privatni party na luksuzno uređenoj terasi modernog objekta uz privatnog barmena, premium catering i DJ-a.', '2026-05-27 11:14:46'),
(3055, 'Čakovec', 'VIP Limuzina tura kroz top međimurske vinarije', 'Pub crawl', 'high', 'Glamurozni večernji izlazak za ekipu, najam luksuzne limuzine s vozačem, privatne vođene degustacije i VIP stolovi u klubovima.', '2026-05-27 11:14:46'),
(3056, 'Čakovec', 'VIP loža i all-inclusive propusnica za Porcijunkulovo', 'Festivali', 'high', 'Praćenje središnjeg programa i gala koncerata iz elitne zatvorene lože uz vrhunski catering, birana međimurska vina i šampanjac.', '2026-05-27 11:14:46'),
(3057, 'Čakovec', 'Najam luksuznog sportskog automobila za vožnju vinskom cestom', 'Road trip', 'high', 'Cjelodnevni najam premium sportskog automobila za ekskluzivnu dinamičnu vožnju slikovitim i zavojitim cestama gornjeg Međimurja.', '2026-05-27 11:14:46'),
(3058, 'Čakovec', 'Ekskluzivni privatni izlet helikopterom iznad Međimurja', 'Boat tour', 'high', 'Panoramski let helikopterom iznad Čakovca, dvorca Zrinskih, rijeka Mure i Drave te zelenih terasastih vinograda s privatnim pilotom.', '2026-05-27 11:14:46');
