INSERT INTO `users` (`id`, `ime`, `prezime`, `email`, `password_hash`, `is_verified`, `verification_token_hash`, `verification_expires_at`, `verified_at`, `reset_token_hash`, `reset_expires_at`, `last_login_at`, `korisnicko_ime`, `bio`, `idealno_putovanje`, `budget`, `putuje_s_kim`, `profilna_slika`, `created_at`, `updated_at`, `title`, `total_xp`) VALUES
(39, 'Leonardo', 'DiCaprio', 'test1@test.com', '$2y$10$oeSuqyLLYHgtE3kjlWFvt.cWbOzhUT4iMYSmWuEpS1xvseGSa8giy', 1, NULL, NULL, '2026-06-03 21:30:44', NULL, NULL, '2026-06-03 22:46:48', 'Nazdravljam_Iz_Inata', 'Uvijek držim čašu u ruci i spreman sam ti čestitati kad ti kôd proradi od prve. Također, primijetio sam jedan bug na ekranu i sad agresivno upirem prstom u njega.', 'plaza', 'veliki', 'partner', 'uploads/user_39_1780518774.jpg', '2026-06-03 20:30:35', '2026-06-03 21:46:48', 'Iskusni putnik', 2000),
(40, 'Ben', 'Affleck', 'test2@test.com', '$2y$10$v7NJw25lJ7OS6YZdQGCH0.VGWyjLr2Y6Vh1lgO1V7y2xlCm8Qh3XO', 1, NULL, NULL, '2026-06-03 21:48:55', NULL, NULL, '2026-06-03 22:36:42', 'Egzistencijalna_Kriza', 'Gledam u prazno dok se tvoja aplikacija učitava. Samo pušim cigaretu ispred kuća i čekam da se sruši produkcija. Ponedjeljak u obliku čovjeka.\"', 'safari', 'srednji', 'svi', 'uploads/user_40_1780519841.jpg', '2026-06-03 20:48:48', '2026-06-03 21:36:42', 'Avanturist', 1200),
(41, 'Pedro', 'Pascal', 'test3@test.com', '$2y$10$a98umgjI39AcVJmRS6OzFOD0KJBb/z1aOswuodAr3LfT.MEQNFv0W', 1, NULL, NULL, '2026-06-03 21:56:12', NULL, NULL, '2026-06-03 21:56:12', 'Smijeh_Pa_Plac', 'Prvo sam se histerično smijao tvojoj aplikaciji, a onda sam počeo nekontrolirano plakati kad sam vidio da nema dark mode. Trenutno žvačem sendvič i gledam u zid.', 'avantura', 'mali', 'sam', 'uploads/user_41_1780520217.jpg', '2026-06-03 20:56:05', '2026-06-03 21:15:19', 'Avanturist', 850),
(42, 'Nicolas', 'Cage', 'test4@test.com', '$2y$10$X/9dsHbkcFznb1XigffyqOCN7RvQ1s2IwxhIi5GkROVKnwgVMtHCa', 1, NULL, NULL, '2026-06-03 22:01:54', NULL, NULL, '2026-06-03 22:01:54', 'Nemoj_Ti_Meni', 'Ono kad mi aplikacija izbaci obavijest \'Dogodila se pogreška\'. Nemoj ti meni?! Širom otvaram oči i radim dramatične ekspresije lica pred kamerom.', 'kruz', 'veliki', 'obitelj', 'uploads/user_42_1780520565.jpg', '2026-06-03 21:01:47', '2026-06-03 21:15:09', 'Radoznali istraživač', 450),
(43, 'Jennifer', 'Lawrence', 'test5@test.com', '$2y$10$/m064nQrMg7HdaoD4sKXHOd.XN4BpmP0bgiG3KmvqSA4m44.xoL2G', 1, NULL, NULL, '2026-06-03 22:06:45', NULL, NULL, '2026-06-03 22:06:45', 'Samo_Sam_Gladna', 'Oprostite ako sam malo oštra. Testiram vašu aplikaciju samo dok čekam pizzu. Nemojte me tjerati da se spotaknem dok koristim sučelje.', 'sve', 'veliki', 'svi', 'uploads/user_43_1780520852.jpg', '2026-06-03 21:06:38', '2026-06-03 21:15:04', 'Iskusni putnik', 1750),
(50, 'Ivan', 'Zdelar', 'ivan@mail.com', '$2y$10$Wf9QOJyQyWfVxs79kGeXpOAHEI4TdMVN.YmZ05RdY5.CiaRmHMU.O', 1, NULL, NULL, '2026-06-03 22:50:10', NULL, NULL, '2026-06-03 22:50:10', 'Zdeks', 'aaa', 'avantura', 'srednji', 'prijatelji', 'uploads/user_50_1780523428.jpg', '2026-06-03 21:50:00', '2026-06-03 21:54:38', 'Avanturist', 950);
